html:
{%- set g = get_timetable_grid(doc.name) -%}
{%- set st = frappe.get_cached_doc("School Settings") -%}
<div class="tt">
  <table class="hd"><tr><td><div class="sn">{{ st.school_name or "" }}</div><div class="mu">Class Timetable</div></td>
  <td style="text-align:right"><div class="cl">{{ doc.stream }}</div><div class="mu">{{ doc.school_term }}</div></td></tr></table>
  <table class="grid">
    <thead><tr><th class="pc">Period</th>{% for d in g.days %}<th>{{ d }}</th>{% endfor %}</tr></thead>
    <tbody>
    {% for row in g.rows %}
      {% if row.period.is_break %}
      <tr class="brk"><td class="pc"><b>{{ row.period.period_name }}</b><br><span class="mu">{{ row.period.time }}</span></td><td colspan="{{ g.days|length }}">{{ row.period.period_name }}</td></tr>
      {% else %}
      <tr><td class="pc"><b>{{ row.period.period_name }}</b><br><span class="mu">{{ row.period.time }}</span></td>
      {% for c in row.cells %}
        <td{% if c and c.color %} style="background:{{ c.color }}22;border-left:3px solid {{ c.color }}"{% endif %}>
        {% if c %}<div class="sub">{{ c.label }}</div><div class="mu">{{ c.teacher }}{% if c.room %} &middot; {{ c.room }}{% endif %}</div>{% endif %}
        </td>
      {% endfor %}</tr>
      {% endif %}
    {% endfor %}
    </tbody>
  </table>
</div>
